def _set_run_font(run, name: str, size: float, color=None, bold=False, rtl=False):
    run.font.name = name
    run.font.size = Pt(size)
    run.bold = bold
    if color:
        run.font.color.rgb = RGBColor(*color)
    rpr = run._element.get_or_add_rPr()
    rfonts = rpr.rFonts
    if rfonts is None:
        rfonts = OxmlElement("w:rFonts")
        rpr.insert(0, rfonts)
    for attr in ("ascii", "hAnsi", "cs", "eastAsia"):
        rfonts.set(qn(f"w:{attr}"), name)
    if rtl:
        rtl_el = OxmlElement("w:rtl")
        rtl_el.set(qn("w:val"), "1")
        rpr.append(rtl_el)


def _set_paragraph_bidi(paragraph, rtl=False):
    ppr = paragraph._p.get_or_add_pPr()
    bidi = ppr.find(qn("w:bidi"))
    if bidi is None:
        bidi = OxmlElement("w:bidi")
        ppr.append(bidi)
    bidi.set(qn("w:val"), "1" if rtl else "0")


def _add_docx_pair(doc, en: str, ur: str, bullet=False):
    p = doc.add_paragraph(style="List Bullet" if bullet else "Normal")
    p.paragraph_format.space_after = Pt(2)
    p.paragraph_format.keep_with_next = True
    p.paragraph_format.left_indent = Inches(0.08 if bullet else 0)
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    _set_paragraph_bidi(p, False)
    r = p.add_run(en)
    _set_run_font(r, "Aptos", 10, (38, 48, 59))
    q = doc.add_paragraph()
    q.paragraph_format.space_after = Pt(8)
    q.paragraph_format.right_indent = Inches(0.04)
    q.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    _set_paragraph_bidi(q, True)
    r2 = q.add_run(ur)
    _set_run_font(r2, "Noto Naskh Arabic", 12, (29, 85, 94), rtl=True)
    return p, q


def _add_docx_heading(doc, en: str, ur: str, level=1):
    p = doc.add_paragraph()
    p.paragraph_format.keep_with_next = True
    p.paragraph_format.space_before = Pt(14 if level == 1 else 8)
    p.paragraph_format.space_after = Pt(1)
    r = p.add_run(en)
    _set_run_font(r, "Aptos Display", 18 if level == 1 else 13, (20, 63, 87), bold=True)
    q = doc.add_paragraph()
    q.paragraph_format.keep_with_next = True
    q.paragraph_format.space_after = Pt(8)
    q.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    _set_paragraph_bidi(q, True)
    r2 = q.add_run(ur)
    _set_run_font(r2, "Noto Naskh Arabic", 17 if level == 1 else 14, (20, 105, 110), bold=True, rtl=True)


def _field(run, instruction):
    fld_char1 = OxmlElement("w:fldChar")
    fld_char1.set(qn("w:fldCharType"), "begin")
    instr = OxmlElement("w:instrText")
    instr.set(qn("xml:space"), "preserve")
    instr.text = instruction
    fld_char2 = OxmlElement("w:fldChar")
    fld_char2.set(qn("w:fldCharType"), "end")
    run._r.append(fld_char1)
    run._r.append(instr)
    run._r.append(fld_char2)


