def _ur(text: str) -> str:
    return get_display(arabic_reshaper.reshape(text))


def _pdf_para(text: str, style, is_urdu=False):
    # Preserve intentional line breaks while escaping text. Apply Urdu shaping
    # independently to each line, never to HTML tags.
    pieces = text.replace("\r\n", "\n").split("\n")
    rendered = []
    for piece in pieces:
        lines = piece.split("<br/>")
        shaped = [_ur(line) if is_urdu else line for line in lines]
        rendered.append("<br/>".join(escape(line) for line in shaped))
    return Paragraph("<br/>".join(rendered), style)


def _draw_page(canvas, doc):
    canvas.saveState()
    w, h = A4
    if doc.page > 1:
        canvas.setStrokeColor(colors.HexColor("#dce7ea"))
        canvas.setLineWidth(0.5)
        canvas.line(17*mm, h-14*mm, w-17*mm, h-14*mm)
        canvas.setFont("DejaVu", 7.5)
        canvas.setFillColor(colors.HexColor("#60727b"))
        canvas.drawString(17*mm, h-11*mm, "PAKISTAN + SINDH  |  COMPANY COMPLIANCE  |  EN–UR")
        canvas.line(17*mm, 13*mm, w-17*mm, 13*mm)
        canvas.drawCentredString(w/2, 8.8*mm, f"Version 1.0  •  22 October 2026  •  Page {doc.page}")
    canvas.restoreState()


def build_pdf():
    pdfmetrics.registerFont(TTFont("DejaVu", str(FONT_EN)))
    pdfmetrics.registerFont(TTFont("DejaVu-Bold", str(FONT_EN_BOLD)))
    pdfmetrics.registerFont(TTFont("NotoUrdu", str(FONT_UR)))
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle("BookTitle", parent=styles["Title"], fontName="DejaVu-Bold", fontSize=24, leading=30, textColor=colors.HexColor("#113d56"), alignment=TA_CENTER, spaceAfter=18)
    subtitle = ParagraphStyle("Subtitle", parent=styles["Normal"], fontName="DejaVu", fontSize=11, leading=16, textColor=colors.HexColor("#42515c"), alignment=TA_CENTER, spaceAfter=8)
    heading = ParagraphStyle("HeadingEN", parent=styles["Heading1"], fontName="DejaVu-Bold", fontSize=15, leading=20, textColor=colors.HexColor("#174f6b"), spaceBefore=12, spaceAfter=2, keepWithNext=True)
    heading_ur = ParagraphStyle("HeadingUR", parent=styles["Normal"], fontName="NotoUrdu", fontSize=17, leading=24, textColor=colors.HexColor("#1c7377"), alignment=TA_RIGHT, wordWrap="RTL", spaceAfter=8, keepWithNext=True)
    body_en = ParagraphStyle("BodyEN", parent=styles["BodyText"], fontName="DejaVu", fontSize=8.8, leading=12.6, textColor=colors.HexColor("#263039"), alignment=TA_LEFT, spaceAfter=3)
    body_ur = ParagraphStyle("BodyUR", parent=styles["BodyText"], fontName="NotoUrdu", fontSize=11.6, leading=18, textColor=colors.HexColor("#285c63"), alignment=TA_RIGHT, wordWrap="RTL", spaceAfter=7)
    toc_en = ParagraphStyle("TocEN", parent=body_en, fontSize=8.8, leading=12, spaceAfter=0)
    toc_ur = ParagraphStyle("TocUR", parent=body_ur, fontSize=10.6, leading=15, spaceAfter=5)
    part_en = ParagraphStyle("PartEN", parent=body_en, fontName="DejaVu-Bold", fontSize=9, leading=12, textColor=colors.HexColor("#1b5b6f"), spaceBefore=8, spaceAfter=0)
    part_ur = ParagraphStyle("PartUR", parent=body_ur, fontSize=12.2, leading=18, textColor=colors.HexColor("#1b5b6f"), spaceAfter=4)
    source_en = ParagraphStyle("SourceEN", parent=body_en, fontSize=7.2, leading=10.3, textColor=colors.HexColor("#42515c"), spaceAfter=1)
    source_ur = ParagraphStyle("SourceUR", parent=body_ur, fontSize=9.5, leading=14, spaceAfter=4)

    doc = BaseDocTemplate(str(PDF_PATH), pagesize=A4, leftMargin=17*mm, rightMargin=17*mm, topMargin=20*mm, bottomMargin=19*mm, title="Pakistan and Sindh Company Compliance Handbook — English and Urdu", author="Compliance Handbook")
    frame = Frame(doc.leftMargin, doc.bottomMargin, doc.width, doc.height, id="normal", leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)
    doc.addPageTemplates([PageTemplate(id="main", frames=frame, onPage=_draw_page)])
    story = []

    def add_pdf_pair(en: str, ur: str, en_style=body_en, ur_style=body_ur):
        story.append(KeepTogether([_pdf_para(en, en_style), _pdf_para(ur, ur_style, True)]))

    # Cover
    story.append(Spacer(1, 36*mm))
    story.append(_pdf_para("PAKISTAN & SINDH<br/>COMPANY COMPLIANCE HANDBOOK", title_style))
    story.append(Spacer(1, 10*mm))
    cover_ur = ParagraphStyle("CoverUR", parent=heading_ur, fontSize=25, leading=37, alignment=TA_RIGHT, wordWrap="RTL", spaceAfter=14)
    story.append(_pdf_para("پاکستان اور سندھ<br/>کمپنی کمپلائنس رہنما کتاب", cover_ur, True))
    story.append(Spacer(1, 4*mm))
